278	// SavePolicy 保存（创建）一条代付策略。
279	//
280	// 出资账户和所有使用账户必须存在，限额必须为正，开始时间必须严格早于
281	// 结束时间，编号不得重复，否则拒绝保存并返回包装了具体原因的错误。
282	func (w *Wallet) SavePolicy(spec PolicySpec) error {
283		if spec.ID == "" {
284			return fmt.Errorf("%w: policy id is required", ErrPolicyInvalid)
285		}
286		if spec.Operation == "" || spec.Payee == "" {
287			return fmt.Errorf("%w: operation and payee are required", ErrPolicyInvalid)
288		}
289		if spec.MaxPerRequest <= 0 || spec.MaxTotal <= 0 {
290			return fmt.Errorf("%w: limits must be positive", ErrPolicyInvalid)
291		}
292		// 审批门槛：零表示关闭；不得为负，不得超过单次上限；开启时等待时长必须为正。
293		if spec.ApprovalThreshold < 0 {
294			return fmt.Errorf("%w: approval threshold must not be negative", ErrPolicyInvalid)
295		}
296		if spec.ApprovalThreshold > 0 {
297			if spec.ApprovalThreshold > spec.MaxPerRequest {
298				return fmt.Errorf("%w: approval threshold %d exceeds per-request limit %d", ErrPolicyInvalid, spec.ApprovalThreshold, spec.MaxPerRequest)
299			}
300			if spec.ApprovalWait <= 0 {
301				return fmt.Errorf("%w: approval wait must be positive when approval is enabled", ErrPolicyInvalid)
302			}
303		}
304		// 最长预留时长：零表示关闭预留超时（保持既有行为）；不得为负。
305		if spec.MaxReserveDuration < 0 {
306			return fmt.Errorf("%w: max reserve duration must not be negative", ErrPolicyInvalid)
307		}
308		if !spec.StartsAt.Before(spec.EndsAt) {
309			return fmt.Errorf("%w: starts-at must be before ends-at", ErrPolicyInvalid)
310		}
311		if spec.PayerAccountID == "" || len(spec.AllowedAccountIDs) == 0 {
312			return fmt.Errorf("%w: payer account and at least one allowed account are required", ErrPolicyInvalid)
313		}
314	
315		w.mu.Lock()
316		defer w.mu.Unlock()
317	
318		if _, ok := w.policies[spec.ID]; ok {
319			return fmt.Errorf("%w: %s", ErrPolicyExists, spec.ID)
320		}
321		if _, ok := w.accounts[spec.PayerAccountID]; !ok {
322			return fmt.Errorf("%w: payer account %q: %w", ErrPolicyInvalid, spec.PayerAccountID, ErrAccountNotFound)
323		}
324		allowed := make(map[string]struct{}, len(spec.AllowedAccountIDs))
325		for _, id := range spec.AllowedAccountIDs {
326			if _, ok := w.accounts[id]; !ok {
327				return fmt.Errorf("%w: allowed account %q: %w", ErrPolicyInvalid, id, ErrAccountNotFound)
328			}
329			allowed[id] = struct{}{}
330		}
331	
332		w.policies[spec.ID] = &policy{
333			id:                 spec.ID,
334			payerAccountID:     spec.PayerAccountID,
335			allowedAccounts:    allowed,
336			operation:          spec.Operation,
337			payee:              spec.Payee,
338			startsAt:           spec.StartsAt,
339			endsAt:             spec.EndsAt,
340			maxPerRequest:      spec.MaxPerRequest,
341			maxTotal:           spec.MaxTotal,
342			approvalThreshold:  spec.ApprovalThreshold,
343			approvalWait:       spec.ApprovalWait,
344			maxReserveDuration: spec.MaxReserveDuration,
345		}
346		return nil
347	}
