349	// Policy 查询策略视图，含当前预留中与已结算的累计金额。查询时已到期的
350	// 预留会先被自动释放，ReservedTotal 因而反映释放后的结果。
351	func (w *Wallet) Policy(id string) (PolicyView, error) {
352		w.mu.Lock()
353		defer w.mu.Unlock()
354	
355		p, ok := w.policies[id]
356		if !ok {
357			return PolicyView{}, fmt.Errorf("%w: %s", ErrPolicyNotFound, id)
358		}
359		w.expireReservationsLocked(w.now())
360		return p.view(), nil
361	}
