363	// DeactivatePolicy 由出资账户主动停用一条代付策略，立即停止该策略继续
364	// 受理代付。停用不可撤销。
365	//
366	// 必须使用该策略出资账户绑定当前设备的有效会话：会话不存在、不属于出资
367	// 账户、设备不符、已吊销或已到期时返回 ErrNotPolicyOwner，不改变策略、
368	// 请求或账本。策略编号、会话编号、设备缺失，或理由去掉首尾空白后为空，
369	// 返回 ErrInvalidArgument。策略不存在返回 ErrPolicyNotFound。保存与比较
370	// 理由均使用去掉首尾空白后的内容。
371	//
372	// 再次停用仍须通过会话校验：理由与首次相同时幂等返回首次结果，理由不同
373	// 返回 ErrConflict；两者都不改写首次停用信息，也不增加账本记录。尚未
374	// 开始或已经结束的策略也允许停用；停用后该编号不能再保存成新策略。
375	//
376	// 停用成功时，该策略下未到等待期限的待审批请求立即转为拒绝终态，拒绝
377	// 信息说明策略被停用并包含停用理由，决定时间为停用时间；已到（含恰到）
378	// 或超过等待期限的待审批请求进入过期终态。两类处理都不冻结余额、不占用
379	// 额度，也不产生退款；其他状态的请求与其他策略不受影响。
380	func (w *Wallet) DeactivatePolicy(policyID, sessionID, deviceID, reason string) (PolicyView, error) {
381		reason = strings.TrimSpace(reason)
382		if policyID == "" || sessionID == "" || deviceID == "" || reason == "" {
383			return PolicyView{}, fmt.Errorf("%w: policy id, session id, device id and reason are required", ErrInvalidArgument)
384		}
385	
386		w.mu.Lock()
387		defer w.mu.Unlock()
388	
389		p, ok := w.policies[policyID]
390		if !ok {
391			return PolicyView{}, fmt.Errorf("%w: %s", ErrPolicyNotFound, policyID)
392		}
393		now := w.now()
394		if err := w.checkPolicyOwnerLocked(p, sessionID, deviceID, now); err != nil {
395			return PolicyView{}, err
396		}
397		// 鉴权通过后先释放已到期预留（停用不缩短任何未到期请求的截止时间）。
398		w.expireReservationsLocked(now)
399	
400		if p.deactivated {
401			// 停用不可撤销：理由相同返回首次结果，理由不同返回冲突，
402			// 均不改写首次信息、不增加账本记录。
403			if p.deactivateReason == reason {
404				return p.view(), nil
405			}
406			return PolicyView{}, fmt.Errorf("%w: policy %s was already deactivated with a different reason", ErrConflict, policyID)
407		}
408	
409		p.deactivated = true
410		p.deactivatedAt = now
411		p.deactivatorAccountID = p.payerAccountID
412		p.deactivateReason = reason
413	
414		w.ledger = append(w.ledger, LedgerEntry{
415			Kind:      LedgerPolicyDeactivation,
416			AccountID: p.payerAccountID,
417			PolicyID:  p.id,
418			Reason:    reason,
419			At:        now,
420		})
421	
422		// 停用瞬间结清该策略全部待审批请求：未到等待期限的随停用立即拒绝，
423		// 已到或超过期限的进入过期终态（不能因未被查询过而变成停用拒绝）。
424		for _, req := range w.requests {
425			if req.policyID != p.id || req.state != RequestPendingApproval {
426				continue
427			}
428			if now.Before(req.waitDeadline) {
429				msg := fmt.Sprintf("policy %s deactivated by payer: %s", p.id, reason)
430				req.state = RequestRejected
431				req.rejectReason = msg
432				req.decidedAt = now
433				req.approverAccountID = p.payerAccountID
434				w.ledger = append(w.ledger, LedgerEntry{
435					Kind:      LedgerRejection,
436					AccountID: req.accountID,
437					RequestID: req.requestID,
438					Reason:    msg,
439					At:        now,
440				})
441				continue
442			}
443			req.state = RequestExpired
444			req.decidedAt = now
445			w.ledger = append(w.ledger, LedgerEntry{
446				Kind:      LedgerExpiration,
447				AccountID: req.accountID,
448				RequestID: req.requestID,
449				Reason:    "approval period expired",
450				At:        now,
451			})
452		}
453		return p.view(), nil
454	}
455	
456	// checkPolicyOwnerLocked 在持锁状态下校验停用会话：必须存在、归属策略的
457	// 出资账户、绑定当前设备、未吊销且未到期。任一不满足都返回
458	// ErrNotPolicyOwner，且不改变策略、请求或账本。
459	func (w *Wallet) checkPolicyOwnerLocked(p *policy, sessionID, deviceID string, now time.Time) error {
460		sess, ok := w.sessions[sessionID]
461		if !ok {
462			return fmt.Errorf("%w: session %s", ErrNotPolicyOwner, sessionID)
463		}
464		if sess.accountID != p.payerAccountID {
465			return fmt.Errorf("%w: session %s belongs to account %s, not payer %s", ErrNotPolicyOwner, sess.id, sess.accountID, p.payerAccountID)
466		}
467		if sess.deviceID != deviceID {
468			return fmt.Errorf("%w: session %s is bound to device %s, not %s", ErrNotPolicyOwner, sess.id, sess.deviceID, deviceID)
469		}
470		if sess.revoked {
471			return fmt.Errorf("%w: session %s revoked", ErrNotPolicyOwner, sess.id)
472		}
473		if !now.Before(sess.expiresAt) {
474			return fmt.Errorf("%w: session %s expired at %s", ErrNotPolicyOwner, sess.id, sess.expiresAt.Format(time.RFC3339))
475		}
476		return nil
477	}
478	
479	// Apply 提交一笔代付申请。
480	//
481	// 校验顺序为：申请字段 -> 使用账户 -> 会话（存在性、归属、设备、吊销、
482	// 到期）-> 幂等请求编号 -> 策略授权与额度 -> 出资账户余额。任一环节
483	// 失败都会在账本中留下带具体原因的拒绝记录，不产生任何扣款或预留。
484	//
485	// 同一使用账户以相同请求编号重复申请：策略、操作类型、收款方和预估
486	// 费用一致时直接返回已有请求（不再预留）；任一不同则返回 ErrConflict。
487	func (w *Wallet) Apply(in RequestInput) (RequestView, error) {
488		if in.EstimatedFee <= 0 {
489			return RequestView{}, w.reject(in, fmt.Errorf("%w: estimated fee must be positive", ErrInvalidAmount))
490		}
491		if in.AccountID == "" || in.SessionID == "" || in.DeviceID == "" || in.RequestID == "" || in.PolicyID == "" {
492			return RequestView{}, w.reject(in, fmt.Errorf("%w: account, session, device, policy and request id are required", ErrInvalidArgument))
493		}
494	
495		w.mu.Lock()
496		defer w.mu.Unlock()
497	
498		now := w.now()
499	
500		acc, ok := w.accounts[in.AccountID]
501		if !ok {
502			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: %s", ErrAccountNotFound, in.AccountID))
503		}
504		_ = acc
505	
506		sess, ok := w.sessions[in.SessionID]
507		if !ok {
508			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: %s", ErrSessionNotFound, in.SessionID))
509		}
510		if sess.accountID != in.AccountID {
511			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: session %s belongs to account %s", ErrSessionAccountMismatch, sess.id, sess.accountID))
512		}
513		if sess.deviceID != in.DeviceID {
514			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: session %s is bound to device %s", ErrSessionDeviceMismatch, sess.id, sess.deviceID))
515		}
516		if sess.revoked {
517			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: session %s", ErrSessionRevoked, sess.id))
518		}
519		// 到期时刻及之后一律视为过期：[零值, ExpiresAt) 才有效。
520		if !now.Before(sess.expiresAt) {
521			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: session %s expired at %s", ErrSessionExpired, sess.id, sess.expiresAt.Format(time.RFC3339)))
522		}
523	
524		key := requestKey{accountID: in.AccountID, requestID: in.RequestID}
525		if existing, ok := w.requests[key]; ok {
526			// 待审批到期即过期、已预留到期即自动退回，重复申请看到的应是最新终态。
527			w.refreshPendingLocked(existing, now)
528			w.refreshReservedLocked(existing, now)
529			if existing.policyID == in.PolicyID &&
530				existing.operation == in.Operation &&
531				existing.payee == in.Payee &&
532				existing.estimatedFee == in.EstimatedFee {
533				// 幂等命中：直接返回已有结果，不再预留、不记账。
534				return existing.view(), nil
535			}
536			return RequestView{}, fmt.Errorf("%w: account %s request %s was already submitted with different content", ErrConflict, in.AccountID, in.RequestID)
537		}
538	
539		p, ok := w.policies[in.PolicyID]
540		if !ok {
541			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: %s", ErrPolicyNotFound, in.PolicyID))
542		}
543		// 停用后的策略不再受理新申请；历史请求的幂等查询在上方已先行处理。
544		if p.deactivated {
545			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: policy %s deactivated: %s", ErrPolicyDeactivated, p.id, p.deactivateReason))
546		}
547		if _, ok := p.allowedAccounts[in.AccountID]; !ok {
548			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: account %s is not allowed by policy %s", ErrPolicyDenied, in.AccountID, p.id))
549		}
550		if in.Operation != p.operation {
551			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: operation %q does not match policy %q", ErrPolicyDenied, in.Operation, p.operation))
552		}
553		if in.Payee != p.payee {
554			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: payee %q does not match policy %q", ErrPolicyDenied, in.Payee, p.payee))
555		}
556		// 时间窗含开始、不含结束：[StartsAt, EndsAt)。
557		if now.Before(p.startsAt) || !now.Before(p.endsAt) {
558			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: current time %s is outside policy window [%s, %s)", ErrPolicyDenied,
559				now.Format(time.RFC3339), p.startsAt.Format(time.RFC3339), p.endsAt.Format(time.RFC3339)))
560		}
561		if in.EstimatedFee > p.maxPerRequest {
562			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: estimated fee %d exceeds per-request limit %d", ErrQuotaExceeded, in.EstimatedFee, p.maxPerRequest))
563		}
564		// 资金与额度检查前释放所有已到期预留（含同一出资账户在其他策略下的
565		// 预留），因此先查余额还是先申请看到的可用金额都一致。
566		w.expireReservationsLocked(now)
567		// 预留中的费用同样占用共享累计额度。
568		if used, exceed := quotaWouldExceedLocked(p, in.EstimatedFee); exceed {
569			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: estimated fee %d would exceed shared total limit %d (used %d)",
570				ErrQuotaExceeded, in.EstimatedFee, p.maxTotal, used))
571		}
572	
573		payer, ok := w.accounts[p.payerAccountID]
574		if !ok {
575			// 保存策略时已校验，这里仅作防御。
576			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("payer account %s: %w", p.payerAccountID, ErrAccountNotFound))
577		}
578		if payer.available < in.EstimatedFee {
579			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: payer %s available %d, need %d", ErrInsufficientBalance, payer.id, payer.available, in.EstimatedFee))
580		}
581	
582		// 所有硬性检查通过：预估费用严格超过审批门槛的进入待审批，其余直接预留。
583		if p.approvalThreshold > 0 && in.EstimatedFee > p.approvalThreshold {
584			// 待审批不冻结余额、不占用共享累计额度。期限取提交时刻 + 等待时长、
585			// 策略结束时间、申请会话到期时间三者中的最早值。
586			deadline := now.Add(p.approvalWait)
587			if p.endsAt.Before(deadline) {
588				deadline = p.endsAt
589			}
590			if sess.expiresAt.Before(deadline) {
591				deadline = sess.expiresAt
592			}
593			req := &request{
594				policyID:       p.id,
595				requestID:      in.RequestID,
596				accountID:      in.AccountID,
597				payerAccountID: payer.id,
598				sessionID:      sess.id,
599				operation:      in.Operation,
600				payee:          in.Payee,
601				estimatedFee:   in.EstimatedFee,
602				state:          RequestPendingApproval,
603				createdAt:      now,
604				waitDeadline:   deadline,
605			}
606			w.requests[key] = req
607			w.ledger = append(w.ledger, LedgerEntry{
608				Kind:      LedgerPendingApproval,
609				AccountID: in.AccountID,
610				RequestID: in.RequestID,
611				Reason:    "pending approval for large amount",
612				At:        now,
613			})
614			return req.view(), nil
615		}
616	
617		// 受理：从出资账户可用余额中预留预估费用。
618		payer.available -= in.EstimatedFee
619		payer.reserved += in.EstimatedFee
620		p.reservedTotal += in.EstimatedFee
621	
622		req := &request{
623			policyID:       p.id,
624			requestID:      in.RequestID,
625			accountID:      in.AccountID,
626			payerAccountID: payer.id,
627			sessionID:      sess.id,
628			operation:      in.Operation,
629			payee:          in.Payee,
630			estimatedFee:   in.EstimatedFee,
631			state:          RequestReserved,
632			createdAt:      now,
633		}
634		// 直接受理：从受理时刻起算最长预留时长。
635		withReserveTimingLocked(req, p, now)
636		w.requests[key] = req
637		w.ledger = append(w.ledger, LedgerEntry{
638			Kind:      LedgerReserve,
639			AccountID: payer.id,
640			RequestID: in.RequestID,
641			Amount:    in.EstimatedFee,
642			Reason:    "reserve estimated fee",
643			At:        now,
644		})
645		return req.view(), nil
646	}
647	
648	// Settle 结算一笔已预留的代付请求。
649	//
650	// actualFee 允许为零但不得为负、不得超过预留的预估费用。结算时扣除
651	// 实际费用并把差额退回可用余额。以相同实际费用重复结算幂等返回，不
652	// 重复记账；不同实际费用返回 ErrConflict。已取消的请求不能结算。
653	func (w *Wallet) Settle(accountID, requestID string, actualFee int64) (RequestView, error) {
654		if actualFee < 0 {
655			return RequestView{}, fmt.Errorf("%w: actual fee must not be negative", ErrInvalidAmount)
656		}
657		w.mu.Lock()
658		defer w.mu.Unlock()
659	
660		req, p, err := w.lookupRequest(accountID, requestID)
661		if err != nil {
662			return RequestView{}, err
663		}
664		now := w.now()
665		w.refreshPendingLocked(req, now)
666		// 已到最长预留时长的预留先自动退回：此后任何结算都不能再扣款。
667		w.refreshReservedLocked(req, now)
668		switch req.state {
669		case RequestSettled:
670			if req.actualFee == actualFee {
671				return req.view(), nil
672			}
673			return RequestView{}, fmt.Errorf("%w: request %s already settled with actual fee %d", ErrConflict, requestID, req.actualFee)
674		case RequestCancelled:
675			return RequestView{}, fmt.Errorf("%w: request %s", ErrAlreadyCancelled, requestID)
676		case RequestReservationExpired:
677			// 预留已超时全额退回：传入非负实际费用也返回明确的超时错误，不能扣款。
678			return RequestView{}, fmt.Errorf("%w: request %s reservation expired at %s", ErrReservationExpired, requestID, req.reserveExpiredAt.Format(time.RFC3339))
679		case RequestPendingApproval, RequestRejected, RequestExpired:
680			// 结算只允许处理已预留请求。
681			return RequestView{}, fmt.Errorf("%w: request %s is %v, only reserved requests can be settled", ErrRequestNotReserved, requestID, req.state)
682		}
683	
684		if actualFee > req.estimatedFee {
685			// 拒绝并保留预留。
686			return RequestView{}, fmt.Errorf("%w: actual %d > estimated %d for request %s", ErrSettleTooLarge, actualFee, req.estimatedFee, requestID)
687		}
688	
689		payer := w.accounts[req.payerAccountID]
690		refund := req.estimatedFee - actualFee
691	
692		// 扣除实际费用、退回差额、释放共享额度。
693		payer.reserved -= req.estimatedFee
694		payer.available += refund
695		p.reservedTotal -= req.estimatedFee
696		p.spentTotal += actualFee
697	
698		req.state = RequestSettled
699		req.actualFee = actualFee
700		req.settledAt = now
701	
702		w.ledger = append(w.ledger, LedgerEntry{
703			Kind:      LedgerSettle,
704			AccountID: payer.id,
705			RequestID: requestID,
706			Amount:    actualFee,
707			Reason:    "settle actual fee",
708			At:        now,
709		})
710		if refund > 0 {
711			w.ledger = append(w.ledger, LedgerEntry{
712				Kind:      LedgerRefund,
713				AccountID: payer.id,
714				RequestID: requestID,
715				Amount:    refund,
716				Reason:    "refund estimated-minus-actual fee",
717				At:        now,
718			})
719		}
720		return req.view(), nil
721	}
722	
723	// Cancel 取消一笔尚未结算的代付请求。
724	//
725	// 待审批请求取消后直接进入取消终态，不产生退款（本就没有冻结余额）；
726	// 已预留请求取消后全部预留退回。已结算的请求不能取消；重复取消幂等
727	// 返回，不重复记账。已拒绝或已过期的请求不能取消。
728	func (w *Wallet) Cancel(accountID, requestID string) (RequestView, error) {
729		w.mu.Lock()
730		defer w.mu.Unlock()
731	
732		req, p, err := w.lookupRequest(accountID, requestID)
733		if err != nil {
734			return RequestView{}, err
735		}
736		now := w.now()
737		w.refreshPendingLocked(req, now)
738		// 已到最长预留时长的预留先自动退回。
739		w.refreshReservedLocked(req, now)
740		switch req.state {
741		case RequestCancelled:
742			return req.view(), nil
743		case RequestSettled:
744			return RequestView{}, fmt.Errorf("%w: request %s", ErrAlreadySettled, requestID)
745		case RequestReservationExpired:
746			// 预留已超时自动全额退回：取消幂等返回已有超时结果，不重复退回、不留痕。
747			return req.view(), nil
748		case RequestPendingApproval:
749			// 待审批取消：无资金冻结，直接留取消终态。
750			req.state = RequestCancelled
751			req.decidedAt = now
752			w.ledger = append(w.ledger, LedgerEntry{
753				Kind:      LedgerCancellation,
754				AccountID: req.accountID,
755				RequestID: req.requestID,
756				Reason:    "cancel pending-approval request",
757				At:        now,
758			})
759			return req.view(), nil
760		case RequestRejected, RequestExpired:
761			return RequestView{}, fmt.Errorf("%w: request %s is %v, cannot cancel", ErrRequestNotReserved, requestID, req.state)
762		}
763	
764		// 已预留：退回全部预留。
765		payer := w.accounts[req.payerAccountID]
766	
767		payer.reserved -= req.estimatedFee
768		payer.available += req.estimatedFee
769		p.reservedTotal -= req.estimatedFee
770	
771		req.state = RequestCancelled
772	
773		w.ledger = append(w.ledger, LedgerEntry{
774			Kind:      LedgerRefund,
775			AccountID: payer.id,
776			RequestID: requestID,
777			Amount:    req.estimatedFee,
778			Reason:    "refund reserved fee on cancel",
779			At:        now,
780		})
781		return req.view(), nil
782	}
783	
784	// Approve 批准一笔待审批的大额代付请求。
785	//
786	// 审批必须使用该策略出资账户绑定当前设备的有效会话；其他账户或无效
787	// 会话返回 ErrNotApprover 无权审批，且不改变请求。批准时再次检查出资
788	// 余额与共享剩余额度，足够才一次性预留全部预估费用并转为已预留；不足
789	// 时返回具体原因，保留待审批状态，期限内可再次批准。
790	//
791	// 已批准并处于预留或结算状态的请求重复批准只返回当前结果，不重复预留；
792	// 已拒绝、过期或取消的请求不能批准。截止时刻及之后不能批准。
793	func (w *Wallet) Approve(accountID, requestID, sessionID, deviceID string) (RequestView, error) {
794		if accountID == "" || requestID == "" || sessionID == "" || deviceID == "" {
795			return RequestView{}, fmt.Errorf("%w: account, request, session and device ids are required", ErrInvalidArgument)
796		}
797		w.mu.Lock()
798		defer w.mu.Unlock()
799	
800		now := w.now()
801		req, p, err := w.lookupRequest(accountID, requestID)
802		if err != nil {
803			return RequestView{}, err
804		}
805		if err := w.checkApproverLocked(req, sessionID, deviceID, now); err != nil {
806			return RequestView{}, err
807		}
808		// 鉴权通过后释放已到期预留（含同一出资账户在其他策略下的预留），使
809		// 批准的余额与额度检查计入退回；因余额或额度不足而失败的批准不会开始
810		// 预留计时。
811		w.expireReservationsLocked(now)
812		w.refreshPendingLocked(req, now)
813		if req.state == RequestExpired {
814			return RequestView{}, fmt.Errorf("%w: approval deadline %s passed", ErrApprovalExpired, req.waitDeadline.Format(time.RFC3339))
815		}
816	
817		switch req.state {
818		case RequestPendingApproval:
819			payer := w.accounts[req.payerAccountID]
820			if payer.available < req.estimatedFee {
821				return RequestView{}, fmt.Errorf("%w: payer %s available %d, need %d", ErrInsufficientBalance, payer.id, payer.available, req.estimatedFee)
822			}
823			if used, exceed := quotaWouldExceedLocked(p, req.estimatedFee); exceed {
824				return RequestView{}, fmt.Errorf("%w: estimated fee %d would exceed shared total limit %d (used %d)",
825					ErrQuotaExceeded, req.estimatedFee, p.maxTotal, used)
826			}
827			// 一次性预留全部预估费用。
828			payer.available -= req.estimatedFee
829			payer.reserved += req.estimatedFee
830			p.reservedTotal += req.estimatedFee
831	
832			req.state = RequestReserved
833			req.decidedAt = now
834			req.approverAccountID = payer.id
835			// 待审批请求：等待审批的时间不计入，从批准成功时刻起算最长预留时长。
836			withReserveTimingLocked(req, p, now)
837	
838			w.ledger = append(w.ledger,
839				LedgerEntry{
840					Kind:      LedgerReserve,
841					AccountID: payer.id,
842					RequestID: req.requestID,
843					Amount:    req.estimatedFee,
844					Reason:    "reserve estimated fee on approval",
845					At:        now,
846				},
847				LedgerEntry{
848					Kind:      LedgerApproval,
849					AccountID: req.accountID,
850					RequestID: req.requestID,
851					Reason:    "approve large-amount request",
852					At:        now,
853				},
854			)
855			return req.view(), nil
856		case RequestReserved, RequestSettled:
857			// 已批准：重复批准幂等返回，不重复预留。
858			return req.view(), nil
859		default:
860			return RequestView{}, fmt.Errorf("%w: request %s is %v, cannot approve", ErrRequestNotPending, requestID, req.state)
861		}
862	}
863	
864	// Reject 拒绝一笔待审批的大额代付请求。
865	//
866	// 拒绝必须使用该策略出资账户绑定当前设备的有效会话；其他账户或无效
867	// 会话返回 ErrNotApprover 无权审批，且不改变请求。拒绝理由为空或全为
868	// 空白时返回 ErrInvalidArgument 参数错误，请求保持不变。
869	//
870	// 重复拒绝且理由一致时幂等返回，不重复留痕；理由不同返回 ErrConflict。
871	// 已批准（含预留、结算）、已过期或已取消的请求不能拒绝。
872	func (w *Wallet) Reject(accountID, requestID, sessionID, deviceID, reason string) (RequestView, error) {
873		if strings.TrimSpace(reason) == "" {
874			return RequestView{}, fmt.Errorf("%w: reject reason must not be empty or blank", ErrInvalidArgument)
875		}
876		if accountID == "" || requestID == "" || sessionID == "" || deviceID == "" {
877			return RequestView{}, fmt.Errorf("%w: account, request, session and device ids are required", ErrInvalidArgument)
878		}
879		w.mu.Lock()
880		defer w.mu.Unlock()
881	
882		now := w.now()
883		req, _, err := w.lookupRequest(accountID, requestID)
884		if err != nil {
885			return RequestView{}, err
886		}
887		if err := w.checkApproverLocked(req, sessionID, deviceID, now); err != nil {
888			return RequestView{}, err
889		}
890		w.refreshPendingLocked(req, now)
891	
892		switch req.state {
893		case RequestPendingApproval:
894			req.state = RequestRejected
895			req.rejectReason = reason
896			req.decidedAt = now
897			req.approverAccountID = req.payerAccountID
898	
899			w.ledger = append(w.ledger, LedgerEntry{
900				Kind:      LedgerRejection,
901				AccountID: req.accountID,
902				RequestID: req.requestID,
903				Reason:    reason,
904				At:        now,
905			})
906			return req.view(), nil
907		case RequestRejected:
908			if req.rejectReason == reason {
909				return req.view(), nil
910			}
911			return RequestView{}, fmt.Errorf("%w: request %s already rejected with a different reason", ErrConflict, requestID)
912		default:
913			return RequestView{}, fmt.Errorf("%w: request %s is %v, cannot reject", ErrRequestNotPending, requestID, req.state)
914		}
915	}
916	
917	// checkApproverLocked 在持锁状态下校验审批会话：必须存在、归属出资账户、
918	// 绑定当前设备、未吊销且未过期。任一不满足都返回 ErrNotApprover，且不
919	// 改变请求。
920	func (w *Wallet) checkApproverLocked(req *request, sessionID, deviceID string, now time.Time) error {
921		sess, ok := w.sessions[sessionID]
922		if !ok {
923			return fmt.Errorf("%w: session %s", ErrNotApprover, sessionID)
924		}
925		if sess.accountID != req.payerAccountID {
926			return fmt.Errorf("%w: session %s belongs to account %s, not payer %s", ErrNotApprover, sess.id, sess.accountID, req.payerAccountID)
927		}
928		if sess.deviceID != deviceID {
929			return fmt.Errorf("%w: session %s is bound to device %s, not %s", ErrNotApprover, sess.id, sess.deviceID, deviceID)
930		}
931		if sess.revoked {
932			return fmt.Errorf("%w: session %s revoked", ErrNotApprover, sess.id)
933		}
934		if !now.Before(sess.expiresAt) {
935			return fmt.Errorf("%w: session %s expired at %s", ErrNotApprover, sess.id, sess.expiresAt.Format(time.RFC3339))
936		}
937		return nil
938	}
939	
940	// refreshPendingLocked 在持锁状态下检查待审批请求是否已到期限；到期
941	// （含到期时刻）则转为过期终态并记账。必须在持锁状态下调用。
942	func (w *Wallet) refreshPendingLocked(req *request, now time.Time) {
943		if req.state != RequestPendingApproval {
944			return
945		}
946		if now.Before(req.waitDeadline) {
947			return
948		}
949		req.state = RequestExpired
950		req.decidedAt = now
951		w.ledger = append(w.ledger, LedgerEntry{
952			Kind:      LedgerExpiration,
953			AccountID: req.accountID,
954			RequestID: req.requestID,
955			Reason:    "approval period expired",
956			At:        now,
957		})
958	}
959	
960	// refreshReservedLocked 在持锁状态下检查单笔已预留请求是否已到最长预留
961	// 时长；截止时刻及之后转为“预留超时”终态并退回全额预留。必须在持锁状态
962	// 下调用。
963	func (w *Wallet) refreshReservedLocked(req *request, now time.Time) {
964		if req.state != RequestReserved || req.reserveDuration <= 0 {
965			return
966		}
967		if now.Before(req.reserveDeadline) {
968			return
969		}
970		w.expireReservationLocked(req, req.reserveDeadline)
971	}
972	
973	// expirePendingApprovalsLocked 惰性结清当前全部已到等待期限（含到期时刻）
974	// 的待审批请求，使它们进入过期终态并留下状态记录。按等待截止时刻顺序
975	// 处理（同截止时刻按使用账户、请求编号排序），保证账本追加顺序确定。
976	// 必须在持锁状态下调用。
977	func (w *Wallet) expirePendingApprovalsLocked(now time.Time) {
978		due := make([]*request, 0)
979		for _, req := range w.requests {
980			if req.state == RequestPendingApproval && !now.Before(req.waitDeadline) {
981				due = append(due, req)
982			}
983		}
984		sort.SliceStable(due, func(i, j int) bool {
985			if due[i].waitDeadline.Equal(due[j].waitDeadline) {
986				if due[i].accountID != due[j].accountID {
987					return due[i].accountID < due[j].accountID
988				}
989				return due[i].requestID < due[j].requestID
990			}
991			return due[i].waitDeadline.Before(due[j].waitDeadline)
992		})
993		for _, req := range due {
994			w.refreshPendingLocked(req, now)
995		}
996	}
997	
998	// expireReservationsLocked 惰性结清当前全部已到期（含到期时刻）的预留。
999	// 所有账户/余额/策略/请求/账本查询以及新申请、批准的资金检查入口都先调用
1000	// 它，因此调用者无须逐笔取消即可看到已到期预留的释放结果。释放时间一律
1001	// 记录为各请求自己的截止时刻，而不是处理时刻；账本按截止时刻顺序追加。
1002	// 必须在持锁状态下调用。
1003	func (w *Wallet) expireReservationsLocked(now time.Time) {
1004		due := make([]*request, 0)
1005		for _, req := range w.requests {
1006			if req.state == RequestReserved && req.reserveDuration > 0 && !now.Before(req.reserveDeadline) {
1007				due = append(due, req)
1008			}
1009		}
1010		sort.SliceStable(due, func(i, j int) bool {
1011			if due[i].reserveDeadline.Equal(due[j].reserveDeadline) {
1012				if due[i].accountID != due[j].accountID {
1013					return due[i].accountID < due[j].accountID
1014				}
1015				return due[i].requestID < due[j].requestID
1016			}
1017			return due[i].reserveDeadline.Before(due[j].reserveDeadline)
1018		})
1019		for _, req := range due {
1020			w.expireReservationLocked(req, req.reserveDeadline)
1021		}
1022	}
1023	
1024	// expireReservationLocked 将一笔已预留请求转为 RequestReservationExpired
1025	// 终态：全额退回预估费用到出资账户可用余额，减少出资账户预留余额与该
1026	// 策略的预留总额，不增加实际费用或已花费总额。账本增加一条出资账户的
1027	// 全额退款记录和一条使用账户的零金额超时状态记录，均关联请求编号。
1028	// 必须在持锁状态下调用。
1029	func (w *Wallet) expireReservationLocked(req *request, deadline time.Time) {
1030		payer := w.accounts[req.payerAccountID]
1031		payer.reserved -= req.estimatedFee
1032		payer.available += req.estimatedFee
1033		if p := w.policies[req.policyID]; p != nil {
1034			p.reservedTotal -= req.estimatedFee
1035		}
1036		req.state = RequestReservationExpired
1037		req.reserveExpiredAt = deadline
1038	
1039		w.ledger = append(w.ledger,
1040			LedgerEntry{
1041				Kind:      LedgerRefund,
1042				AccountID: payer.id,
1043				RequestID: req.requestID,
1044				Amount:    req.estimatedFee,
1045				Reason:    "refund reserved fee on reservation timeout",
1046				At:        deadline,
1047			},
1048			LedgerEntry{
1049				Kind:      LedgerReservationExpiration,
1050				AccountID: req.accountID,
1051				RequestID: req.requestID,
1052				Reason:    "reservation timed out before settlement",
1053				At:        deadline,
1054			},
1055		)
1056	}
1057	
1058	// withReserveTimingLocked 在费用完成预留时写入预留计时信息：预留时刻为
1059	// 受理/批准成功的时刻，截止时刻为预留时刻加策略最长预留时长；策略未启用
1060	// 超时（时长为零）时截止时刻保持零值。必须在持锁状态下调用。
1061	func withReserveTimingLocked(req *request, p *policy, reservedAt time.Time) {
1062		req.reservedAt = reservedAt
1063		req.reserveDuration = p.maxReserveDuration
1064		if p.maxReserveDuration > 0 {
1065			req.reserveDeadline = reservedAt.Add(p.maxReserveDuration)
1066		}
1067	}
1068	
1069	// quotaWouldExceedLocked 判断在策略 p 上再计入 fee 后，共享累计合计是否
1070	// 严格超过累计上限，并返回计入前“现存预留 + 已结算实际费用”的合计（用于
1071	// 错误信息；该合计本身越过 int64 范围时返回 0）。现存预留、已结算实际费用
1072	// 与本次费用各自合法、但合计越过 int64 范围时 exceed 同样为 true：不能让
1073	// 求和回绕成小（或负）数后被当成额度充足。累计上限与单次上限仍允许取
1074	// int64 最大值，这里不缩小金额范围。必须在持锁状态下调用。
1075	func quotaWouldExceedLocked(p *policy, fee int64) (used int64, exceed bool) {
1076		used, ok := addInt64(p.reservedTotal, p.spentTotal)
1077		if !ok {
1078			return 0, true
1079		}
1080		total, ok := addInt64(used, fee)
1081		if !ok {
1082			return used, true
1083		}
1084		return used, total > p.maxTotal
1085	}
1086	
1087	// Request 查询某使用账户下的代付请求。待审批请求到期即转为过期终态，
1088	// 已预留请求到最长预留时长即转为预留超时终态，查询结果反映最新状态；
1089	// 超时释放时间记录的是截止时刻本身，而不是本次查询时刻。
1090	func (w *Wallet) Request(accountID, requestID string) (RequestView, error) {
1091		w.mu.Lock()
1092		defer w.mu.Unlock()
1093	
1094		req, _, err := w.lookupRequest(accountID, requestID)
1095		if err != nil {
1096			return RequestView{}, err
1097		}
1098		now := w.now()
1099		w.refreshPendingLocked(req, now)
1100		w.refreshReservedLocked(req, now)
1101		return req.view(), nil
1102	}
1103	
1104	// Ledger 返回全部账本记录的副本，按产生顺序排列。
1105	// 申请被拒绝的记录（Kind 为 LedgerRejection）也包含在内并带有原因。
1106	// 查询时已到期预留的自动退款与超时留痕也会在返回前补齐。
1107	func (w *Wallet) Ledger() []LedgerEntry {
1108		w.mu.Lock()
1109		defer w.mu.Unlock()
1110	
1111		w.expireReservationsLocked(w.now())
1112		out := make([]LedgerEntry, len(w.ledger))
1113		copy(out, w.ledger)
1114		return out
1115	}
1116	
1117	// AccountLedger 返回与指定账户相关的账本记录副本。
1118	//
1119	// 对出资账户返回预留、扣减、退回等资金变动记录；对待审批、批准、拒绝、
1120	// 取消、过期等状态记录（无金额变动），其 AccountID 为发起申请的使用
1121	// 账户，因此按使用账户查询可看到该请求的完整状态留痕。
1122	func (w *Wallet) AccountLedger(accountID string) []LedgerEntry {
1123		w.mu.Lock()
1124		defer w.mu.Unlock()
1125	
1126		w.expireReservationsLocked(w.now())
1127		var out []LedgerEntry
1128		for _, e := range w.ledger {
1129			if e.AccountID == accountID {
1130				out = append(out, e)
1131			}
1132		}
1133		return out
1134	}
1135	
1136	// lookupRequest 必须在持锁状态下调用。
1137	func (w *Wallet) lookupRequest(accountID, requestID string) (*request, *policy, error) {
1138		req, ok := w.requests[requestKey{accountID: accountID, requestID: requestID}]
1139		if !ok {
1140			return nil, nil, fmt.Errorf("%w: account %s request %s", ErrRequestNotFound, accountID, requestID)
1141		}
1142		return req, w.policies[req.policyID], nil
1143	}
1144	
1145	// reject 记录无需持锁快速校验阶段的拒绝（当前没有此类调用，保留对称接口）。
1146	func (w *Wallet) reject(in RequestInput, cause error) error {
1147		w.mu.Lock()
1148		defer w.mu.Unlock()
1149		w.appendRejection(in, w.now(), cause)
1150		return cause
1151	}
1152	
1153	// rejectLocked 在持锁状态下记录拒绝原因并原样返回错误。
1154	func (w *Wallet) rejectLocked(in RequestInput, at time.Time, cause error) error {
1155		w.appendRejection(in, at, cause)
1156		return cause
1157	}
1158	
1159	// appendRejection 必须在持锁状态下调用。拒绝记录不涉及金额变动，
1160	// 只记录使用账户、请求编号与具体原因。
1161	func (w *Wallet) appendRejection(in RequestInput, at time.Time, cause error) {
1162		w.ledger = append(w.ledger, LedgerEntry{
1163			Kind:      LedgerRejection,
1164			AccountID: in.AccountID,
1165			RequestID: in.RequestID,
1166			Reason:    cause.Error(),
1167			At:        at,
1168		})
1169	}
1170	
1171	func (a *account) view() AccountView {
1172		return AccountView{
1173			ID: a.id,
1174			Balances: Balances{
1175				Available: a.available,
1176				Reserved:  a.reserved,
1177			},
1178			CreatedAt: a.createdAt,
1179		}
1180	}
1181	
1182	func (s *session) view() SessionView {
1183		state := SessionActive
1184		if s.revoked {
1185			state = SessionRevoked
1186		}
1187		return SessionView{
1188			ID:        s.id,
1189			AccountID: s.accountID,
1190			DeviceID:  s.deviceID,
1191			ExpiresAt: s.expiresAt,
1192			State:     state,
1193			CreatedAt: s.createdAt,
1194		}
1195	}
1196	
1197	func (p *policy) view() PolicyView {
1198		ids := make([]string, 0, len(p.allowedAccounts))
1199		for id := range p.allowedAccounts {
1200			ids = append(ids, id)
1201		}
1202		return PolicyView{
1203			PolicySpec: PolicySpec{
1204				ID:                 p.id,
1205				PayerAccountID:     p.payerAccountID,
1206				AllowedAccountIDs:  ids,
1207				Operation:          p.operation,
1208				Payee:              p.payee,
1209				StartsAt:           p.startsAt,
1210				EndsAt:             p.endsAt,
1211				MaxPerRequest:      p.maxPerRequest,
1212				MaxTotal:           p.maxTotal,
1213				ApprovalThreshold:  p.approvalThreshold,
1214				ApprovalWait:       p.approvalWait,
1215				MaxReserveDuration: p.maxReserveDuration,
1216			},
1217			ReservedTotal:        p.reservedTotal,
1218			SpentTotal:           p.spentTotal,
1219			Deactivated:          p.deactivated,
1220			DeactivatedAt:        p.deactivatedAt,
1221			DeactivatorAccountID: p.deactivatorAccountID,
1222			DeactivateReason:     p.deactivateReason,
1223		}
1224	}
1225	
1226	func (r *request) view() RequestView {
1227		return RequestView{
1228			PolicyID:          r.policyID,
1229			RequestID:         r.requestID,
1230			AccountID:         r.accountID,
1231			PayerAccountID:    r.payerAccountID,
1232			Operation:         r.operation,
1233			Payee:             r.payee,
1234			EstimatedFee:      r.estimatedFee,
1235			ActualFee:         r.actualFee,
1236			State:             r.state,
1237			CreatedAt:         r.createdAt,
1238			SettledAt:         r.settledAt,
1239			WaitDeadline:      r.waitDeadline,
1240			ReservedAt:        r.reservedAt,
1241			ReserveDuration:   r.reserveDuration,
1242			ReserveDeadline:   r.reserveDeadline,
1243			ReserveExpiredAt:  r.reserveExpiredAt,
1244			DecidedAt:         r.decidedAt,
1245			ApproverAccountID: r.approverAccountID,
1246			RejectReason:      r.rejectReason,
1247		}
1248	}
