1207	// ---- 策略共享累计额度 ----
1208	
1209	// quotaReqSpec 描述累计额度测试备份中的一条请求。
1210	type quotaReqSpec struct {
1211		id           string
1212		account      string // "u1" 或 "u2"
1213		estFee       int64
1214		actualFee    int64
1215		state        RequestState
1216		due          bool   // 已预留请求的截止时刻是否早于恢复时刻 t0
1217		wasReserved  bool   // RequestCancelled 时标识“已预留后取消”
1218		rejectReason string // RequestRejected 使用
1219	}
1220	
1221	// quotaPolicySpec 描述一条策略及其请求。
1222	type quotaPolicySpec struct {
1223		id                    string
1224		per, total, threshold int64
1225		wait, reserveDur      time.Duration
1226		reqs                  []quotaReqSpec
1227	}
1228	
1229	// buildCumulativeQuotaBackup 构造资金完全自洽的备份：账户预留余额、各策略
1230	// 预留/已花费总额均按“现存已预留请求的预估费用”和“已结算请求的实际费用”
1231	// 求和填写，因此余额与各项总额核对必然通过，能否恢复只取决于累计额度判断。
1232	func buildCumulativeQuotaBackup(t *testing.T, t0 time.Time, policies []quotaPolicySpec) []byte {
1233		t.Helper()
1234		b := backupV1{
1235			Version:    backupVersion,
1236			ExportedAt: timeJSON(t0),
1237			Accounts: []accountBackupV1{
1238				{ID: "payer", Available: 0, Reserved: 0, CreatedAt: timeJSON(t0)},
1239				{ID: "u1", Available: 0, Reserved: 0, CreatedAt: timeJSON(t0)},
1240				{ID: "u2", Available: 0, Reserved: 0, CreatedAt: timeJSON(t0)},
1241			},
1242			Sessions: []sessionBackupV1{
1243				{ID: "s1", AccountID: "u1", DeviceID: "d1", ExpiresAt: timeJSON(t0.Add(24 * time.Hour)), CreatedAt: timeJSON(t0)},
1244				{ID: "s2", AccountID: "u2", DeviceID: "d2", ExpiresAt: timeJSON(t0.Add(24 * time.Hour)), CreatedAt: timeJSON(t0)},
1245			},
1246			Policies: make([]policyBackupV1, 0, len(policies)),
1247			Requests: make([]requestBackupV1, 0),
1248			Ledger:   []ledgerEntryBackupV1{},
1249		}
1250		sessionOf := map[string]string{"u1": "s1", "u2": "s2"}
1251	
1252		var accountReserved int64
1253		for _, ps := range policies {
1254			var reservedTotal, spentTotal int64
1255			b.Policies = append(b.Policies, policyBackupV1{
1256				ID: ps.id, PayerAccountID: "payer", AllowedAccountIDs: []string{"u1", "u2"},
1257				Operation: "charge", Payee: "shop",
1258				StartsAt: timeJSON(t0.Add(-time.Hour)), EndsAt: timeJSON(t0.Add(24 * time.Hour)),
1259				MaxPerRequest:      ps.per,
1260				MaxTotal:           ps.total,
1261				ApprovalThreshold:  ps.threshold,
1262				ApprovalWait:       durationJSON(ps.wait),
1263				MaxReserveDuration: durationJSON(ps.reserveDur),
1264			})
1265			for _, rs := range ps.reqs {
1266				r := requestBackupV1{
1267					PolicyID: ps.id, RequestID: rs.id, AccountID: rs.account, PayerAccountID: "payer",
1268					SessionID: sessionOf[rs.account], Operation: "charge", Payee: "shop",
1269					EstimatedFee: rs.estFee, ActualFee: rs.actualFee,
1270					State:     int(rs.state),
1271					CreatedAt: timeJSON(t0),
1272				}
1273				reservedOrigin := rs.state == RequestReserved || rs.state == RequestSettled ||
1274					rs.state == RequestReservationExpired ||
1275					(rs.state == RequestCancelled && rs.wasReserved)
1276				switch rs.state {
1277				case RequestPendingApproval, RequestRejected, RequestExpired:
1278					r.WaitDeadline = timeJSON(t0.Add(ps.wait))
1279				case RequestCancelled:
1280					if !reservedOrigin {
1281						r.DecidedAt = timeJSON(t0)
1282					}
1283				}
1284				if rs.state == RequestRejected {
1285					r.DecidedAt = timeJSON(t0)
1286					r.RejectReason = rs.rejectReason
1287				}
1288				if rs.state == RequestExpired {
1289					r.DecidedAt = timeJSON(t0.Add(ps.wait))
1290				}
1291				if reservedOrigin {
1292					reservedAt := t0
1293					if rs.due || rs.state == RequestReservationExpired {
1294						reservedAt = t0.Add(-2 * ps.reserveDur)
1295					}
1296					r.ReservedAt = timeJSON(reservedAt)
1297					r.ReserveDuration = durationJSON(ps.reserveDur)
1298					if ps.reserveDur > 0 {
1299						r.ReserveDeadline = timeJSON(reservedAt.Add(ps.reserveDur))
1300					}
1301					if ps.threshold > 0 && rs.estFee > ps.threshold {
1302						r.ApproverAccountID = "payer"
1303						r.DecidedAt = timeJSON(reservedAt)
1304					}
1305				}
1306				if rs.state == RequestSettled {
1307					r.SettledAt = timeJSON(time.Time(r.ReservedAt).Add(ps.reserveDur))
1308				}
1309				if rs.state == RequestReservationExpired {
1310					r.ReserveExpiredAt = r.ReserveDeadline
1311				}
1312				b.Requests = append(b.Requests, r)
1313	
1314				switch rs.state {
1315				case RequestReserved:
1316					sum, ok := addInt64(reservedTotal, rs.estFee)
1317					if !ok {
1318						t.Fatalf("test setup: reserved sum overflow")
1319					}
1320					reservedTotal = sum
1321					sum, ok = addInt64(accountReserved, rs.estFee)
1322					if !ok {
1323						t.Fatalf("test setup: account reserved overflow")
1324					}
1325					accountReserved = sum
1326				case RequestSettled:
1327					sum, ok := addInt64(spentTotal, rs.actualFee)
1328					if !ok {
1329						t.Fatalf("test setup: spent sum overflow")
1330					}
1331					spentTotal = sum
1332				}
1333			}
1334			for i := range b.Policies {
1335				if b.Policies[i].ID == ps.id {
1336					b.Policies[i].ReservedTotal = reservedTotal
1337					b.Policies[i].SpentTotal = spentTotal
1338				}
1339			}
1340		}
1341		for i := range b.Accounts {
1342			if b.Accounts[i].ID == "payer" {
1343				b.Accounts[i].Reserved = accountReserved
1344			}
1345		}
1346		data, err := json.Marshal(&b)
1347		if err != nil {
1348			t.Fatal(err)
1349		}
1350		return data
1351	}
