1405					{
1406						id: "p1", per: 100, total: 50,
1407						reqs: []quotaReqSpec{
1408							{id: "s1", account: "u1", estFee: 30, actualFee: 20, state: RequestSettled},
1409							{id: "r1", account: "u1", estFee: 30, state: RequestReserved},
1410						},
1411					},
1412					{
1413						id: "p2", per: 100, total: 50,
1414						reqs: []quotaReqSpec{
1415							{id: "s2", account: "u1", estFee: 30, actualFee: 21, state: RequestSettled},
1416							{id: "r2", account: "u1", estFee: 30, state: RequestReserved},
1417						},
1418					},
1419				},
1420				restoreAt:  t0,
1421				wantPolicy: "p2",
1422			},
1423		}
1424		for _, tc := range cases {
1425			t.Run(tc.name, func(t *testing.T) {
1426				data := buildCumulativeQuotaBackup(t, t0, tc.policies)
1427				w2, err := restoreAt(data, tc.restoreAt)
1428				if err == nil {
1429					if w2 != nil {
1430						t.Fatalf("over-quota backup restored a wallet")
1431					}
1432					t.Fatalf("over-quota backup restored without error")
1433				}
1434				if !errors.Is(err, ErrBackupInvalid) {
1435					t.Fatalf("err = %v, want ErrBackupInvalid", err)
1436				}
1437				msg := err.Error()
1438				if !strings.Contains(msg, tc.wantPolicy) {
1439					t.Fatalf("error %q must name policy %q", msg, tc.wantPolicy)
