1448	// TestRestoreRejectsPolicyCumulativeQuotaOverflow 验证预留与已花费各自都能
1449	// 由 int64 表示、合计却越过 int64 上限时必须拒绝，不能因金额越界误判为
1450	// 额度充足。
1451	func TestRestoreRejectsPolicyCumulativeQuotaOverflow(t *testing.T) {
1452		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
1453		data := buildCumulativeQuotaBackup(t, t0, []quotaPolicySpec{{
1454			id: "p-big", per: math.MaxInt64, total: math.MaxInt64,
1455			reqs: []quotaReqSpec{
1456				{id: "settled", account: "u1", estFee: math.MaxInt64, actualFee: math.MaxInt64, state: RequestSettled},
1457				{id: "reserved", account: "u1", estFee: 1, state: RequestReserved},
1458			},
1459		}})
1460		w2, err := restoreAt(data, t0)
1461		if err == nil {
1462			if w2 != nil {
1463				t.Fatalf("overflowing-quota backup restored a wallet")
1464			}
1465			t.Fatalf("overflowing-quota backup restored without error")
1466		}
1467		if !errors.Is(err, ErrBackupInvalid) {
1468			t.Fatalf("err = %v, want ErrBackupInvalid", err)
1469		}
1470		msg := err.Error()
1471		if !strings.Contains(msg, "p-big") || !strings.Contains(msg, "cumulative total limit") {
1472			t.Fatalf("error %q must name policy and cumulative limit", msg)
1473		}
1474	}
1475	
1476	// TestRestoreAcceptsCumulativeQuotaAtBoundary 验证合计恰好等于累计上限合法，
1477	// 包括上限恰为 int64 最大值的情况；不缩小现有金额范围。
1478	func TestRestoreAcceptsCumulativeQuotaAtBoundary(t *testing.T) {
1479		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
1480	
1481		// 上限 50：结算实际 20（预估 30，差额已退回）+ 现存预留 30 = 50。
1482		data := buildCumulativeQuotaBackup(t, t0, []quotaPolicySpec{{
1483			id: "p-eq", per: 30, total: 50,
1484			reqs: []quotaReqSpec{
1485				{id: "settled", account: "u1", estFee: 30, actualFee: 20, state: RequestSettled},
1486				{id: "reserved", account: "u1", estFee: 30, state: RequestReserved},
1487			},
1488		}})
1489		if _, err := restoreAt(data, t0); err != nil {
1490			t.Fatalf("used == total restore: %v", err)
1491		}
1492	
1493		// 上限 MaxInt64：已花费 MaxInt64-1 + 预留 1 = MaxInt64。
1494		data = buildCumulativeQuotaBackup(t, t0, []quotaPolicySpec{{
1495			id: "p-max", per: math.MaxInt64, total: math.MaxInt64,
1496			reqs: []quotaReqSpec{
1497				{id: "settled", account: "u1", estFee: math.MaxInt64, actualFee: math.MaxInt64 - 1, state: RequestSettled},
1498				{id: "reserved", account: "u1", estFee: 1, state: RequestReserved},
1499			},
1500		}})
1501		if _, err := restoreAt(data, t0); err != nil {
1502			t.Fatalf("used == MaxInt64 restore: %v", err)
1503		}
1504	
1505		// 上限 MaxInt64：单笔已结算实际费用 MaxInt64，占满额度。
1506		data = buildCumulativeQuotaBackup(t, t0, []quotaPolicySpec{{
1507			id: "p-spent-max", per: math.MaxInt64, total: math.MaxInt64,
1508			reqs: []quotaReqSpec{
1509				{id: "settled", account: "u1", estFee: math.MaxInt64, actualFee: math.MaxInt64, state: RequestSettled},
1510			},
1511		}})
1512		if _, err := restoreAt(data, t0); err != nil {
1513			t.Fatalf("spent == MaxInt64 restore: %v", err)
1514		}
1515	
1516		// 上限 MaxInt64：单笔预估费用 MaxInt64 的现存预留占满额度。
1517		data = buildCumulativeQuotaBackup(t, t0, []quotaPolicySpec{{
1518			id: "p-reserved-max", per: math.MaxInt64, total: math.MaxInt64,
1519			reqs: []quotaReqSpec{
1520				{id: "reserved", account: "u1", estFee: math.MaxInt64, state: RequestReserved},
1521			},
1522		}})
1523		if _, err := restoreAt(data, t0); err != nil {
1524			t.Fatalf("reserved == MaxInt64 restore: %v", err)
1525		}
1526	
1527		// 不同策略分别判断：同一出资账户的两条策略各自恰好占满 50，
1528		// 跨策略合计 100 不影响合法性。
1529		data = buildCumulativeQuotaBackup(t, t0, []quotaPolicySpec{
1530			{
1531				id: "p1", per: 100, total: 50,
1532				reqs: []quotaReqSpec{
1533					{id: "s1", account: "u1", estFee: 30, actualFee: 20, state: RequestSettled},
1534					{id: "r1", account: "u1", estFee: 30, state: RequestReserved},
1535				},
1536			},
1537			{
1538				id: "p2", per: 100, total: 50,
1539				reqs: []quotaReqSpec{
1540					{id: "s2", account: "u2", estFee: 30, actualFee: 20, state: RequestSettled},
1541					{id: "r2", account: "u2", estFee: 30, state: RequestReserved},
1542				},
1543			},
1544		})
1545		if _, err := restoreAt(data, t0); err != nil {
1546			t.Fatalf("two policies each at their own limit: %v", err)
1547		}
1548	}
1549	
1550	// TestRestoreCumulativeQuotaIgnoresNonOccupyingStates 验证只有现存预留与已
1551	// 结算实际费用占用累计额度：待审批、审批拒绝、待审批取消、待审批过期、已
1552	// 预留后取消、预留超时的请求都不占用；结算退回的差额也不计入已花费。
1553	func TestRestoreCumulativeQuotaIgnoresNonOccupyingStates(t *testing.T) {
1554		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
1555		// 累计上限仅 10：一笔实际费用 10 的已结算请求占满额度；其余请求费用均
1556		// 为 30（待审批系严格超过门槛 10），但都不占用额度，备份仍合法。
1557		data := buildCumulativeQuotaBackup(t, t0, []quotaPolicySpec{{
1558			id: "p-free", per: 100, total: 10, threshold: 10,
1559			wait: 5 * time.Minute, reserveDur: time.Minute,
1560			reqs: []quotaReqSpec{
1561				{id: "settled", account: "u1", estFee: 10, actualFee: 10, state: RequestSettled},
1562				{id: "reserved-cancelled", account: "u1", estFee: 10, state: RequestCancelled, wasReserved: true},
1563				{id: "reservation-expired", account: "u1", estFee: 10, state: RequestReservationExpired},
1564				{id: "pending", account: "u1", estFee: 30, state: RequestPendingApproval},
1565				{id: "rejected", account: "u1", estFee: 30, state: RequestRejected, rejectReason: "no"},
1566				{id: "pending-expired", account: "u1", estFee: 30, state: RequestExpired},
1567				{id: "pending-cancelled", account: "u1", estFee: 30, state: RequestCancelled},
1568			},
1569		}})
1570		w2, err := restoreAt(data, t0)
1571		if err != nil {
1572			t.Fatalf("non-counting states restore: %v", err)
1573		}
1574		// 未到期的待审批请求不被改写；没有任何现存预留，账户预留余额为零。
1575		r, err := w2.Request("u1", "pending")
1576		if err != nil || r.State != RequestPendingApproval {
1577			t.Fatalf("pending request state = %v err = %v, want still pending", r.State, err)
1578		}
1579		if bal, _ := w2.Balance("payer"); bal != (Balances{Available: 0, Reserved: 0}) {
1580			t.Fatalf("payer balance = %+v, want zero reserved", bal)
1581		}
1582	}
1583	
1584	// ---- 并发 ----
1585	
1586	func TestExportConcurrentWithMutations(t *testing.T) {
1587		w, c := newTestWallet()
1588		t0 := c.t
1589		mustAccount(t, w, "payer", 1_000_000)
1590		mustAccount(t, w, "u1", 0)
1591		mustAccount(t, w, "u2", 0)
1592		if _, err := w.CreateSession("s1", "u1", "dev1", t0.Add(24*time.Hour)); err != nil {
1593			t.Fatal(err)
1594		}
1595		if _, err := w.CreateSession("s2", "u2", "dev2", t0.Add(24*time.Hour)); err != nil {
1596			t.Fatal(err)
1597		}
1598		if err := w.SavePolicy(PolicySpec{
1599			ID: "p1", PayerAccountID: "payer", AllowedAccountIDs: []string{"u1", "u2"},
1600			Operation: "charge", Payee: "shop",
1601			StartsAt: t0.Add(-time.Hour), EndsAt: t0.Add(24 * time.Hour),
1602			MaxPerRequest: 100, MaxTotal: 1_000_000,
1603			MaxReserveDuration: time.Hour,
1604		}); err != nil {
1605			t.Fatal(err)
1606		}
1607	
1608		const n = 200
1609		var wg sync.WaitGroup
1610		var backups [][]byte
1611		var mu sync.Mutex
1612	
1613		// 申请/结算/取消/导出 并发；每个备份都必须是可恢复的完整状态。
1614		for g := 0; g < 4; g++ {
1615			g := g
1616			wg.Add(1)
1617			go func() {
1618				defer wg.Done()
1619				for i := 0; i < n; i++ {
1620					rid := fmt.Sprintf("g%d-r%d", g, i)
1621					in := RequestInput{
1622						PolicyID: "p1", RequestID: rid, AccountID: "u2", SessionID: "s2",
1623						DeviceID: "dev2", Operation: "charge", Payee: "shop", EstimatedFee: 1,
1624					}
1625					if _, err := w.Apply(in); err != nil {
1626						t.Errorf("apply: %v", err)
1627						return
1628					}
1629					switch i % 3 {
1630					case 0:
1631						if _, err := w.Settle("u2", rid, 1); err != nil {
1632							t.Errorf("settle: %v", err)
1633						}
1634					case 1:
1635						if _, err := w.Cancel("u2", rid); err != nil {
1636							t.Errorf("cancel: %v", err)
1637						}
1638					}
1639				}
1640			}()
1641		}
1642		wg.Add(1)
1643		go func() {
1644			defer wg.Done()
1645			for i := 0; i < n; i++ {
1646				data, err := w.Export()
1647				if err != nil {
1648					t.Errorf("export: %v", err)
1649					return
1650				}
1651				mu.Lock()
1652				backups = append(backups, data)
1653				mu.Unlock()
1654			}
1655		}()
1656		wg.Wait()
1657	
1658		if len(backups) == 0 {
1659			t.Fatal("no backups captured")
1660		}
1661		for i, data := range backups {
1662			w2, err := Restore(data)
1663			if err != nil {
1664				t.Fatalf("backup %d not restorable: %v", i, err)
1665			}
1666			// 恢复出的钱包余额自洽：非负且预留不凭空消失。
1667			for _, id := range []string{"payer"} {
1668				bal, err := w2.Balance(id)
1669				if err != nil {
1670					t.Fatalf("backup %d balance: %v", i, err)
1671				}
1672				if bal.Available < 0 || bal.Reserved < 0 {
1673					t.Fatalf("backup %d negative balance: %+v", i, bal)
1674				}
1675			}
1676		}
1677	
1678		// 最终状态本身也必须可导出/恢复且账本完整（用与源钱包相同的受控时刻，
1679		// 避免恢复时钟把未到期预留结算掉而混淆比较）。
1680		final, err := w.Export()
1681		if err != nil {
1682			t.Fatal(err)
1683		}
1684		w2, err := restoreAt(final, c.t)
1685		if err != nil {
1686			t.Fatal(err)
1687		}
1688		if l1, l2 := len(w.Ledger()), len(w2.Ledger()); l1 != l2 {
1689			t.Fatalf("final ledger length = %d, want %d", l2, l1)
1690		}
1691	}
1692

