1	package wallet
2	
3	import (
4		"encoding/json"
5		"errors"
6		"math"
7		"testing"
8		"time"
9	)
10	
11	// buildMaxQuotaBackup 构造一份资金自洽的备份：策略 p-big 的单次与累计上限
12	// 均为 int64 最大值，含一笔已结算请求（预估 MaxInt64、实际 MaxInt64-1，
13	// 即已花费 MaxInt64-1），没有现存预留；出资账户可用余额由 available 指定。
14	// 使用账户 u1（会话 s1/设备 d1）、u2（会话 s2/设备 d2）共享额度。
15	// threshold>0 时策略开启审批（等待 1 小时），已结算大额请求按备份自洽要求
16	// 携带批准信息。
17	func buildMaxQuotaBackup(t *testing.T, t0 time.Time, threshold, available int64) []byte {
18		t.Helper()
19		const spent = math.MaxInt64 - 1
20		r := requestBackupV1{
21			PolicyID: "p-big", RequestID: "settled", AccountID: "u1", PayerAccountID: "payer",
22			SessionID: "s1", Operation: "charge", Payee: "shop",
23			EstimatedFee: math.MaxInt64, ActualFee: spent,
24			State:      int(RequestSettled),
25			CreatedAt:  timeJSON(t0.Add(-2 * time.Hour)),
26			ReservedAt: timeJSON(t0.Add(-2 * time.Hour)),
27			SettledAt:  timeJSON(t0.Add(-time.Hour)),
28		}
29		// 开启审批时该笔费用严格超过门槛，备份自洽要求带批准人与决定时刻。
30		if threshold > 0 {
31			r.ApproverAccountID = "payer"
32			r.DecidedAt = r.ReservedAt
33		}
34		b := backupV1{
35			Version: backupVersion,
36			// ExportedAt 在校验中不使用，给出 t0 保持可读。
37			ExportedAt: timeJSON(t0),
38			Accounts: []accountBackupV1{
39				{ID: "payer", Available: available, Reserved: 0, CreatedAt: timeJSON(t0)},
40				{ID: "u1", Available: 0, Reserved: 0, CreatedAt: timeJSON(t0)},
41				{ID: "u2", Available: 0, Reserved: 0, CreatedAt: timeJSON(t0)},
42			},
43			Sessions: []sessionBackupV1{
44				{ID: "s1", AccountID: "u1", DeviceID: "d1", ExpiresAt: timeJSON(t0.Add(24 * time.Hour)), CreatedAt: timeJSON(t0)},
45				{ID: "s2", AccountID: "u2", DeviceID: "d2", ExpiresAt: timeJSON(t0.Add(24 * time.Hour)), CreatedAt: timeJSON(t0)},
46			},
47			Policies: []policyBackupV1{{
48				ID: "p-big", PayerAccountID: "payer", AllowedAccountIDs: []string{"u1", "u2"},
49				Operation: "charge", Payee: "shop",
50				StartsAt: timeJSON(t0.Add(-time.Hour)), EndsAt: timeJSON(t0.Add(24 * time.Hour)),
51				MaxPerRequest:     math.MaxInt64,
52				MaxTotal:          math.MaxInt64,
53				ApprovalThreshold: threshold,
54				ApprovalWait:      durationJSON(time.Hour),
55				SpentTotal:        spent,
56			}},
57			Requests: []requestBackupV1{r},
58			Ledger:   []ledgerEntryBackupV1{},
59		}
60		data, err := json.Marshal(&b)
61		if err != nil {
62			t.Fatal(err)
63		}
64		return data
65	}
66	
67	// maxQuotaApply 构造一笔针对 p-big 策略的申请。
68	func maxQuotaApply(account, session, device, rid string, fee int64) RequestInput {
69		return RequestInput{
70			PolicyID:     "p-big",
71			RequestID:    rid,
72			AccountID:    account,
73			SessionID:    session,
74			DeviceID:     device,
75			Operation:    "charge",
76			Payee:        "shop",
77			EstimatedFee: fee,
78		}
79	}
80	
81	// TestApplySharedQuotaOverflowRejected 验证题述场景：累计上限为 int64 最大
82	// 值、已花费 MaxInt64-1、无现存预留、出资账户可用余额为 10 时，新申请预估
83	// 费用 2 必须按超额度拒绝（不能因求和越过 int64 上限被当成额度充足），费用
84	// 1 恰好把合计推到上限，应正常受理。
85	func TestApplySharedQuotaOverflowRejected(t *testing.T) {
86		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
87		data := buildMaxQuotaBackup(t, t0, 0, 10)
88		w, err := restoreAt(data, t0)
89		if err != nil {
90			t.Fatalf("valid at-boundary backup must restore: %v", err)
91		}
92	
93		// 费用 2：used=MaxInt64-1，合计越过 int64 上限 → 超额度拒绝。
94		in := maxQuotaApply("u1", "s1", "d1", "over", 2)
95		if _, err := w.Apply(in); !errors.Is(err, ErrQuotaExceeded) {
96			t.Fatalf("apply fee 2 err = %v, want ErrQuotaExceeded", err)
97		}
98		// 不创建请求。
99		if _, err := w.Request("u1", "over"); !errors.Is(err, ErrRequestNotFound) {
100			t.Fatalf("rejected apply created request: %v", err)
101		}
102		// 不扣减可用余额、不新增预留。
103		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 10, Reserved: 0}) {
104			t.Fatalf("balance after rejected apply = %+v, want {10 0}", bal)
105		}
106		pv, _ := w.Policy("p-big")
107		if pv.ReservedTotal != 0 || pv.SpentTotal != math.MaxInt64-1 {
108			t.Fatalf("policy totals after rejected apply = reserved %d spent %d", pv.ReservedTotal, pv.SpentTotal)
109		}
110		// 按现有申请拒绝规则留下一条带原因的拒绝记录，且无资金变动。
111		led := w.Ledger()
112		if len(led) != 1 || led[0].Kind != LedgerRejection || led[0].RequestID != "over" || led[0].Amount != 0 {
113			t.Fatalf("ledger after rejected apply = %+v", led)
114		}
115		if led[0].Reason == "" {
116			t.Fatal("rejection reason must not be empty")
117		}
118		if len(w.AccountLedger("payer")) != 0 {
119			t.Fatalf("rejected apply must not move payer money: %+v", w.AccountLedger("payer"))
120		}
121	
122		// 费用 1：合计恰好等于 MaxInt64 上限，正常受理并预留。
123		fit := maxQuotaApply("u1", "s1", "d1", "fit", 1)
124		req, err := w.Apply(fit)
125		if err != nil {
126			t.Fatalf("apply fee 1 at exact boundary: %v", err)
